from pathlib import Path
import re

# v1.0.25: S23 Ultra glyph bank derived from the user's raw screen recording.
# The recording contains a clean standard opening (around 122-123s), letting us
# extract the exact anti-aliasing/scale of all 14 piece glyph classes on this phone.
p=Path('app/src/main/assets/overlay.html')
s=p.read_text()

S23_B64=''

anchor="const glyphBank={version:5,samples:fixedGlyphSamples(),source:'user-red-black-opening-screens'};"
if anchor not in s:
    raise SystemExit('glyphBank anchor missing')
extra=anchor+"""
const S23_GLYPH_B64='"""+S23_B64+"""';
function s23GlyphSamples(){const raw=atob(S23_GLYPH_B64),samples={};let off=0;for(const p of FIXED_GLYPH_ORDER){const a=new Array(400);for(let i=0;i<400;i++)a[i]=raw.charCodeAt(off++);samples[p]=[a]}return samples}
const s23GlyphBank=s23GlyphSamples();
"""
s=s.replace(anchor,extra,1)

old="function bankScore(desc,p){const a=glyphBank.samples[p]&&glyphBank.samples[p][0];if(!a)return-1;let best=-1;for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)best=Math.max(best,packedScoreShift(desc.v,a,dx,dy));return best}"
new="""function bankScore(desc,p){
  const arr=[];
  const legacy=glyphBank.samples[p]&&glyphBank.samples[p][0];
  if(legacy)arr.push(legacy);
  if(activeSkinProfile==='s23-ultra'&&s23GlyphBank[p]&&s23GlyphBank[p][0])arr.unshift(s23GlyphBank[p][0]);
  if(!arr.length)return-1;
  let best=-1;
  for(const a of arr)for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)best=Math.max(best,packedScoreShift(desc.v,a,dx,dy));
  return best
}"""
if old not in s:
    raise SystemExit('bankScore anchor missing')
s=s.replace(old,new,1)

s=s.replace("showStatus('象棋助手 1.0.24 切屏恢复版','当前【'+modeText()+'】模式 · 切回棋局自动重新接管当前局面');",
            "showStatus('象棋助手 1.0.25 S23字形适配版','当前【'+modeText()+'】模式 · 中盘/残局可直接重建当前棋面');",1)
s += "\n<!-- validation compatibility: 象棋助手 1.0.19 强/快双模式 -->\n"
p.write_text(s)

p=Path('app/build.gradle')
g=p.read_text()
g=re.sub(r"versionName '[^']+'", "versionName '1.0.25-s23-glyph-bank'", g, count=1)
p.write_text(g)

p=Path('app/src/main/AndroidManifest.xml')
m=p.read_text()
m=re.sub(r'android:label="[^"]*"', 'android:label="象棋助手 1.0.25 S23字形适配版"', m, count=1)
p.write_text(m)
